structureCode.vanilla:
// Raiz + indicador: div[data-slot="progress"] > .nds-progress-indicator
const bar = createProgress({
  value: 42,          // null ativa o modo indeterminado
  max: 100,
  variant: 'success', // ausente, a bar usa o primário
  // Obrigatório: sem nome, a bar é anunciada só como percentual.
  'aria-label': 'Enviando arquivo',
});

extensibilityCode.react:
// Cor semântica da barra
<Progress value={progress} data-variant="success" aria-label="Sincronização" />

// Texto anunciado no lugar do percentual
<Progress
  value={42}
  aria-label="Processamento de arquivos"
  getAriaValueText={(_formatted, value) =>
    value === null ? 'Contando arquivos' : `${value} de 100 arquivos`}
/>

extensibilityCode.vanilla:
// Cor semântica da barra
const bar = createProgress({
  value: progress,
  variant: 'success',
  'aria-label': 'Sincronização',
});

// Texto anunciado no lugar do percentual
const files = createProgress({
  value: 42,
  'aria-label': 'Processamento de arquivos',
  getAriaValueText: (value, min, max) =>
    value === null ? 'Contando arquivos' : `${value} de ${max} arquivos`,
});

customizationCode.web:
/* Cor da barra numa instância só: a folha lê --nds-progress-color e cai
   no primário quando ela não existe. */
.upload-progress { --nds-progress-color: var(--info); }

/* Ciclo do traço indeterminado nesta instância */
.upload-progress[data-indeterminate] { --duration-stately: 2s; }

